package com.lmspilot.notification.api;
import com.lmspilot.notification.domain.*;import com.lmspilot.support.api.ApiException;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.time.*;import java.util.*;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.bind.annotation.*;
record NotificationTemplateRequest(@NotBlank String code,@NotBlank String eventType,@NotBlank String titleTemplate,@NotBlank String bodyTemplate,Boolean active){}record NotificationTemplateResponse(UUID id,String code,String eventType,String titleTemplate,String bodyTemplate,boolean active,Instant updatedAt){}record NotificationReminderRuleRequest(@NotBlank String name,ReminderRuleType type,UUID templateId,@Min(0) @Max(365) Integer daysBeforeDue,Boolean enabled){}record NotificationReminderRuleResponse(UUID id,String name,ReminderRuleType type,UUID templateId,int daysBeforeDue,boolean enabled,Instant nextRunAt,Instant updatedAt){}record ReminderRunResponse(UUID ruleId,int matched,int dispatched,int duplicate,LocalDate targetDate){}
@Service @Transactional class NotificationAutomationService{private final NotificationTemplateRepository templates;private final NotificationReminderRuleRepository rules;private final NotificationReminderDispatchRepository dispatches;NotificationAutomationService(NotificationTemplateRepository t,NotificationReminderRuleRepository r,NotificationReminderDispatchRepository d){templates=t;rules=r;dispatches=d;}List<NotificationTemplateResponse> templates(){return templates.findAllByOrderByCodeAsc().stream().map(this::view).toList();}NotificationTemplateResponse saveTemplate(UUID id,NotificationTemplateRequest i){NotificationTemplateEntity e=id==null?new NotificationTemplateEntity():templates.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"TEMPLATE_NOT_FOUND","Không tìm thấy mẫu"));if(id==null&&templates.findByCodeIgnoreCase(i.code()).isPresent())throw new ApiException(HttpStatus.CONFLICT,"TEMPLATE_CODE_EXISTS","Mã mẫu đã tồn tại");e.code=i.code().trim().toUpperCase(Locale.ROOT);e.eventType=i.eventType().trim();e.titleTemplate=i.titleTemplate();e.bodyTemplate=i.bodyTemplate();e.active=i.active()==null||i.active();e.updatedAt=Instant.now();return view(templates.save(e));}void deleteTemplate(UUID id){templates.deleteById(id);}List<NotificationReminderRuleResponse> rules(){return rules.findAllByOrderByCreatedAtDesc().stream().map(this::view).toList();}NotificationReminderRuleResponse saveRule(UUID id,NotificationReminderRuleRequest i){templates.findById(i.templateId()).orElseThrow(()->new ApiException(HttpStatus.BAD_REQUEST,"TEMPLATE_NOT_FOUND","Không tìm thấy mẫu"));NotificationReminderRuleEntity e=id==null?new NotificationReminderRuleEntity():rules.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"RULE_NOT_FOUND","Không tìm thấy quy tắc"));e.name=i.name().trim();e.type=i.type()==null?ReminderRuleType.COURSE_DUE:i.type();e.templateId=i.templateId();e.daysBeforeDue=i.daysBeforeDue()==null?1:i.daysBeforeDue();e.enabled=i.enabled()==null||i.enabled();e.nextRunAt=Instant.now().plus(Duration.ofDays(1));e.updatedAt=Instant.now();return view(rules.save(e));}void deleteRule(UUID id){rules.deleteById(id);}ReminderRunResponse run(UUID id){NotificationReminderRuleEntity e=rules.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"RULE_NOT_FOUND","Không tìm thấy quy tắc"));e.nextRunAt=Instant.now().plus(Duration.ofDays(1));rules.save(e);return new ReminderRunResponse(id,0,0,0,LocalDate.now().plusDays(e.daysBeforeDue));}private NotificationTemplateResponse view(NotificationTemplateEntity e){return new NotificationTemplateResponse(e.id,e.code,e.eventType,e.titleTemplate,e.bodyTemplate,e.active,e.updatedAt);}private NotificationReminderRuleResponse view(NotificationReminderRuleEntity e){return new NotificationReminderRuleResponse(e.id,e.name,e.type,e.templateId,e.daysBeforeDue,e.enabled,e.nextRunAt,e.updatedAt);}}
@RestController @RequestMapping("/api/v1/notifications/templates") public class NotificationAutomationApi{private final NotificationAutomationService service;public NotificationAutomationApi(NotificationAutomationService s){service=s;}@GetMapping public List<NotificationTemplateResponse> list(){return service.templates();}@PostMapping @ResponseStatus(HttpStatus.CREATED) public NotificationTemplateResponse create(@Valid @RequestBody NotificationTemplateRequest i){return service.saveTemplate(null,i);}@PutMapping("/{id}") public NotificationTemplateResponse update(@PathVariable UUID id,@Valid @RequestBody NotificationTemplateRequest i){return service.saveTemplate(id,i);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) public void delete(@PathVariable UUID id){service.deleteTemplate(id);}}
@RestController @RequestMapping("/api/v1/notifications/reminder-rules") class NotificationReminderController{private final NotificationAutomationService service;NotificationReminderController(NotificationAutomationService s){service=s;}@GetMapping List<NotificationReminderRuleResponse> list(){return service.rules();}@PostMapping @ResponseStatus(HttpStatus.CREATED) NotificationReminderRuleResponse create(@Valid @RequestBody NotificationReminderRuleRequest i){return service.saveRule(null,i);}@PutMapping("/{id}") NotificationReminderRuleResponse update(@PathVariable UUID id,@Valid @RequestBody NotificationReminderRuleRequest i){return service.saveRule(id,i);}@DeleteMapping("/{id}") @ResponseStatus(HttpStatus.NO_CONTENT) void delete(@PathVariable UUID id){service.deleteRule(id);}@PostMapping("/{id}/run") ReminderRunResponse run(@PathVariable UUID id){return service.run(id);}}
